class K{String s(boolean p,String I){var l=I.lines().toList();int h=l.size(),w=l.get(0).length(),n=0,x[]=new int[h*w],y[]=new int[h*w];int[] R=new int[h],C=new int[w];for(int i=0;i<h;i++)for(int j=0;j<w;j++)if(l.get(i).charAt(j)<40){x[n]=j;y[n++]=i;R[i]=C[j]=1;}long r=0,z=p?1:999999;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++){long a=Math.abs(x[i]-x[j]),b=Math.abs(y[i]-y[j]);for(int k=x[i];k!=x[j];)if(C[k+=x[i]<x[j]?1:-1]<1)a+=z;for(int k=y[i];k!=y[j];)if(R[k+=y[i]<y[j]?1:-1]<1)b+=z;r+=a+b;}return r+"";}}
